actions.script:
groups = []
failedSources = []
approvalCount = 0
itemCount = 0
counts = {overdue: 0, dueToday: 0, laterToday: 0, eventsToday: 0, sourceItems: 0, total: 0}
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const nowMillis = toMillis(ec.user.nowTimestamp)
// a Date: a time-only pattern (h:mm a) on a time stamp or its millis text answers the millis
const fmt = (millis, pattern) => ec.l10n.format(new Date(Number(millis)), pattern)
const L = (text) => ec.l10n.localize(text)
dayLabel = fmt(nowMillis, 'EEEE, MMM d')
const today = fmt(nowMillis, 'yyyy-MM-dd')
const timeOf = (millis) => fmt(millis, 'h:mm a')
// a day of the last week by its name, an older one by its date
const dayOf = (millis) => nowMillis - millis < 6 * 86400000 ? fmt(millis, 'EEE') : fmt(millis, 'MMM d')
const icons = {task: 'sym_o_task_alt', call: 'sym_o_call', email: 'sym_o_mail', todo: 'sym_o_checklist', meeting: 'sym_o_groups',
    event: 'sym_o_event', request: 'sym_o_support', approval: 'sym_o_how_to_reg', timer: 'sym_o_timer', timesheet: 'sym_o_schedule_send',
    review: 'sym_o_rate_review', triage: 'sym_o_inbox'}
const kindLabels = {task: 'Task', call: 'Call', email: 'Email', todo: 'To-do', meeting: 'Meeting', event: 'Event', request: 'Request',
    timer: 'Timer', timesheet: 'Timesheet', review: 'Review', triage: 'To triage'}
// a link as attribute text of the panel's markup
const attr = (text) => text == null ? null : String(text).replace(/[&<>"]/g, (ch) => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;'})[ch])
const link = (parameters) => {
    try {
        return ec.service.sync().name('ironstone.commons.PaletteServices.get#RecordLink').parameters(parameters).call() || {}
    } catch (err) {
        ec.logger.warn(`Today: no link for ${JSON.stringify(parameters)}: ${err && err.message ? err.message : err}`)
        return {}
    }
}

const out = ec.service.sync().name('mantle.work.WorkEffortServices.get#UserTodayItems')
        .parameters({sourceServiceNames: sourceServiceNames || []}).call() || {}
if (ec.message.hasError()) return
approvalCount = out.approvalCount || 0

const decorate = (item, group) => {
    const kind = item.kind || 'task'
    const isEvent = kind === 'event' || kind === 'meeting'
    const due = toMillis(item.dueDate)
    const start = toMillis(item.startDate)
    const end = toMillis(item.endDate)
    let timeText = ''
    if (kind === 'request') {
        timeText = item.overdue && due != null ? L('Overdue since') + ' ' + dayOf(due) : (due != null ? L('Response due') + ' ' + timeOf(due) : '')
    } else if (kind === 'timer') {
        // Projects' running timer (mantle.work.ProjectServices.get#ProjectTodayItems)
        timeText = start != null ? L('Running since') + ' ' + (nowMillis - start < 20 * 3600000 ? timeOf(start) : dayOf(start) + ' ' + timeOf(start)) : L('Running')
    } else if (kind === 'timesheet') {
        timeText = item.overdue ? L('Not submitted') : L('Week ends')
    } else if (kind === 'review' || kind === 'triage') {
        timeText = ''
    } else if (isEvent) {
        if (item.allDay) timeText = L('All day')
        else if (start != null && start <= nowMillis) timeText = end != null ? L('Now, until') + ' ' + timeOf(end) : L('Now')
        else if (start != null) timeText = timeOf(start) + (end != null ? ' – ' + timeOf(end) : '')
    } else if (due != null) {
        if (group === 'overdue') timeText = L('Overdue since') + ' ' + dayOf(due)
        else timeText = fmt(due, 'HH:mm') === '00:00' ? L('Today') : L('Due') + ' ' + timeOf(due)
    } else if (start != null) timeText = timeOf(start)

    let url = null
    if (item.workEffortId) url = link({recordEntityName: 'mantle.work.effort.WorkEffort', id: item.workEffortId,
        workEffortTypeEnumId: isEvent ? 'WetEvent' : 'WetTask'}).url
    else if (item.requestId) url = link({docType: 'MantleRequest', id: item.requestId}).url
    else if (item.url) url = String(item.url)
    // Projects' timesheet to submit opens its week in My time (People's own item, impl-people P10, names its mount's)
    if (kind === 'timesheet' && item.weekStart && !item.url) url = '/qapps/Projects/Time/MyTime?weekDate=' + encodeURIComponent(item.weekStart)
    const record = item.record || null
    let recordCaption = null
    let recordUrl = null
    // a request item's record is the request itself
    if (record && !(item.requestId && record.recordEntityName === 'mantle.request.Request' && record.recordId === item.requestId)) {
        recordCaption = record.recordName || null
        recordUrl = link({recordEntityName: record.recordEntityName, id: record.recordId}).url || null
    }
    if (!url && record && record.recordId) url = link({recordEntityName: record.recordEntityName, id: record.recordId}).url || null
    const assignees = Array.from(item.assignees || []).map((assignee) => assignee.name).filter((name) => name)
    const canComplete = !isEvent && !!item.workEffortId && !!item.canUpdate
    return {kind: kind, kindLabel: L(kindLabels[kind] || 'Item'), icon: icons[kind] || 'sym_o_radio_button_unchecked',
        workEffortId: item.workEffortId || null, requestId: item.requestId || null, title: item.title || item.workEffortId || item.requestId || '',
        url: url, urlAttr: attr(url), timeText: timeText, recordCaption: recordCaption, recordUrl: recordUrl, recordUrlAttr: attr(recordUrl),
        assigneeText: assignees.length ? L('with') + ' ' + assignees.join(', ') : null,
        priority: item.priority ?? null, statusId: item.statusId ?? null, allDay: !!item.allDay, isEvent: isEvent,
        overdue: group === 'overdue' || !!item.overdue, canComplete: canComplete, canReschedule: canComplete,
        canSnooze: !!item.workEffortId, dueDateText: due != null ? fmt(due, 'yyyy-MM-dd') : today, source: item.source || null,
        canStopTimer: kind === 'timer' && !!item.timeEntryId, timeEntryId: item.timeEntryId || null}
}
const builtIn = [['overdue', 'Overdue', true], ['dueToday', 'Due today', false], ['laterToday', 'Later today', false]]
for (const [key, label, warning] of builtIn) {
    const items = Array.from(out[key] || []).map((item) => decorate(item, key))
    counts[key] = items.length
    counts.eventsToday += key === 'overdue' ? 0 : items.filter((item) => item.isEvent).length
    groups.push({key: key, label: L(label), warning: warning, isSource: false, items: items})
}
let index = 0
for (const source of Array.from(out.sourceGroups || [])) {
    const items = Array.from(source.items || []).map((item) => decorate(item, item.overdue ? 'overdue' : 'source'))
    counts.sourceItems += items.length
    groups.push({key: 'source' + (index++), label: source.label || source.service, warning: false, isSource: true, items: items})
}
for (const failure of Array.from(out.failedSources || [])) {
    const builtInFailed = failure.service === 'mantle.work.WorkEffortServices.get#UserTodayItems'
    failedSources.push({label: failure.label || (builtInFailed ? L('Tasks and events') : String(failure.service || '')), service: failure.service})
}
counts.total = counts.overdue + counts.dueToday + counts.laterToday + counts.sourceItems
itemCount = counts.total

const partyId = ec.user.userAccount?.partyId
const cf = ec.entity.conditionFactory
const row = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
const mine = row != null && partyId && (row.ownerPartyId === partyId || ec.entity.find('mantle.work.effort.WorkEffortParty')
        .condition('workEffortId', workEffortId).condition('partyId', partyId).condition('roleTypeId', 'Assignee')
        .condition(cf.makeConditionDate('fromDate', 'thruDate', ec.user.nowTimestamp))
        .condition(cf.makeCondition('statusId', 'not-in', ['WeptDeclined', 'WeptUnassigned'], true)).count() > 0)
if (!mine || row.workEffortTypeEnumId !== 'WetTask') {
    ec.message.addError(ec.resource.expand('You may not change task ${workEffortId}', '', {workEffortId: workEffortId}))
    return
}
// a maintenance work order and its steps are changed only through their lifecycle in Maintenance (impl-maintenance P3)
if (ec.resource.script('component://mr-mantle/service/mantle/work/WorkProcesses.js').managedIds([workEffortId]).length) {
    ec.message.addError(ec.resource.expand('MANAGED_WORK: Work ${workEffortId} is a maintenance work order\'s: complete it from its work order in Maintenance', '', {workEffortId: workEffortId}))
    return
}
// a production run's operation is changed only through Manufacturing's production services (impl-manufacturing F38)
const productionRun = (id) => !!id && ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id)
        .selectField('purposeEnumId').disableAuthz().one()?.purposeEnumId === 'WepProductionRun'
if (row.purposeEnumId === 'WepProductionRun' || productionRun(row.rootWorkEffortId) || productionRun(row.parentWorkEffortId)) {
    ec.message.addError(ec.resource.expand('Operation ${workEffortId} is production work: record it on the shop floor in Manufacturing', '', {workEffortId: workEffortId}))
    return
}
workEffort = row.getMap()

const text = String(estimatedCompletionDate).trim()
const old = checked.workEffort.estimatedCompletionDate
let time = '00:00'
if (old != null && old !== '') time = ec.l10n.format(old, 'HH:mm')
const withTime = /^\d{4}-\d{2}-\d{2}$/.test(text) ? text + ' ' + time : text.substring(0, 16)
estimatedCompletionDate = ec.l10n.parseTimestamp(withTime + ':00.000', 'yyyy-MM-dd HH:mm:ss.SSS')
if (estimatedCompletionDate == null) ec.message.addError(ec.resource.expand('Not a date: ${text}', '', {text: text}))

rows = []
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const L = (text) => ec.l10n.localize(text)
const nowMillis = toMillis(ec.user.nowTimestamp)
// a Date: a time-only pattern (h:mm a) on a time stamp or its millis text answers the millis
const fmt = (millis, pattern) => ec.l10n.format(new Date(Number(millis)), pattern)
const today = fmt(nowMillis, 'yyyy-MM-dd')
const yesterday = fmt(nowMillis - 86400000, 'yyyy-MM-dd')
const whenText = (millis) => {
    if (millis == null) return ''
    const minutes = Math.floor((nowMillis - millis) / 60000)
    if (minutes < 1) return L('Just now')
    if (minutes < 60) return ec.resource.expand('${minutes} min ago', '', {minutes: minutes})
    const day = fmt(millis, 'yyyy-MM-dd')
    if (day === today) return ec.resource.expand('${hours} h ago', '', {hours: Math.floor(minutes / 60)})
    if (day === yesterday) return L('Yesterday') + ' ' + fmt(millis, 'h:mm a')
    if (nowMillis - millis < 6 * 86400000) return fmt(millis, 'EEE h:mm a')
    return fmt(millis, 'MMM d')
}
const reasons = {NrMention: ['sym_o_alternate_email', 'Mention'], NrAssignment: ['sym_o_assignment_ind', 'Assignment'],
    NrApproval: ['sym_o_how_to_reg', 'Approval'], NrDateAlert: ['sym_o_event_upcoming', 'Date alert'], NrReminder: ['sym_o_alarm', 'Reminder'],
    NrComment: ['sym_o_comment', 'Comment'], NrSystem: ['sym_o_info', 'System']}
// the record-update topics of Mantle's data feed name their record in the message
const topicRecords = {MantleTask: ['mantle.work.effort.WorkEffort', 'workEffortId'], MantleEvent: ['mantle.work.effort.WorkEffort', 'workEffortId'],
    MantleRequest: ['mantle.request.Request', 'requestId'], MantleCommunicationEvent: ['mantle.party.communication.CommunicationEvent', 'communicationEventId']}
const titles = appTitles || {}
const hiddenItems = ec.resource.script('component://mr-boss/service/ironstone/projects/HiddenItems.js')
for (const row of Array.from(notificationList || [])) {
    const message = row.message && typeof row.message === 'object' ? row.message : {}
    let recordEntityName = row.recordEntityName || null
    let recordId = row.recordId || null
    if (!recordEntityName && topicRecords[row.topic] && message[topicRecords[row.topic][1]]) {
        recordEntityName = topicRecords[row.topic][0]
        recordId = message[topicRecords[row.topic][1]]
    }
    // a notification of a task the user may not see (no longer on its project, or a confidential issue's the user is
    // no Owner of) is not shown: its title and summary would name it (projects/HiddenItems.js mayName)
    if (recordEntityName === 'mantle.work.effort.WorkEffort' && recordId && !hiddenItems.mayName(recordId)
            && ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', recordId).disableAuthz().one()?.workEffortTypeEnumId === 'WetTask') continue
    let openUrl = null
    // an approval topic's card opens the topic's own screen link first (the place its approver decides it, such as
    // Maintenance's BookingRequests for ResourceBooking, impl-maintenance P16 review R8), else the record's as any card
    const ownLink = row.canApprove && row.linkText && /^\/q?apps\//.test(String(row.linkText))
            && !/^\/q?apps\/Commons\/openRecord\?/.test(String(row.linkText)) ? String(row.linkText) : null
    if (ownLink) openUrl = ownLink
    else if (recordEntityName && recordId) {
        try {
            openUrl = ec.service.sync().name('ironstone.commons.PaletteServices.get#RecordLink')
                    .parameters({recordEntityName: recordEntityName, id: recordId}).call()?.url || null
        } catch (err) {
            ec.logger.warn(`Notification ${row.notificationMessageId}: no link for ${recordEntityName} ${recordId}: ${err && err.message ? err.message : err}`)
        }
    }
    // a link through the record-link resolver (Commons' openRecord: the timesheet topics, impl-people P10) opens where the
    // resolver sends this user, as the email's link does
    const resolver = !openUrl && row.linkText ? /^\/q?apps\/Commons\/openRecord\?(.*)$/.exec(String(row.linkText)) : null
    if (resolver) {
        const asked = {}
        for (const pair of resolver[1].split('&')) {
            const at = pair.indexOf('=')
            if (at > 0) asked[decodeURIComponent(pair.substring(0, at))] = decodeURIComponent(pair.substring(at + 1).replace(/\+/g, ' '))
        }
        try {
            if (asked.id) openUrl = ec.service.sync().name('ironstone.commons.PaletteServices.get#RecordLink').parameters({docType: asked.docType || null,
                    recordEntityName: asked.recordEntityName || null, id: asked.id}).call()?.url || null
        } catch (err) {
            ec.logger.warn(`Notification ${row.notificationMessageId}: no link for ${row.linkText}: ${err && err.message ? err.message : err}`)
        }
    } else if (!openUrl && row.linkText) openUrl = String(row.linkText)
    const sent = toMillis(row.userSentDate) ?? toMillis(row.sentDate)
    const reason = reasons[row.reasonEnumId] || ['sym_o_notifications', null]
    const isApproval = !!row.canApprove && !row.viewedDate
    let summary = message.summary ? String(message.summary) : null
    if (isApproval && message.amount) summary = (summary ? summary + ' · ' : '') + (message.currencyUomId ?
            ec.l10n.formatCurrency(message.amount, message.currencyUomId) : String(message.amount))
    rows.push(Object.assign({}, row, {recordEntityName: recordEntityName, recordId: recordId, icon: reason[0],
        reasonLabel: reason[1] ? L(reason[1]) : null, appLabel: row.appName ? (titles[row.appName] || row.appName) : null,
        whenText: whenText(sent), unread: !row.viewedDate, isApproval: isApproval, summary: summary,
        requestedByName: message.requestedByName || row.actorName || null,
        openUrl: openUrl, openIsScreen: !!openUrl && /^\/(qapps|apps)\//.test(openUrl)}))
}

const row = ec.entity.find('moqui.security.user.NotificationMessageByUser').condition('userId', ec.user.userId)
        .condition('notificationMessageId', notificationMessageId).disableAuthz().one()
if (row == null) { ec.message.addError(ec.resource.expand('Notification ${notificationMessageId} not found', '', {notificationMessageId: notificationMessageId})); return }
titleText = row.titleText
let message = null
try { message = row.messageJson ? JSON.parse(row.messageJson) : null } catch (err) { message = null }
const decorated = ec.service.sync().name('ironstone.commons.CommonsServices.decorate#Notifications').parameters({notificationList: [{
    notificationMessageId: row.notificationMessageId, topic: row.topic, recordEntityName: row.recordEntityName, recordId: row.recordId,
    linkText: row.linkText, message: message, sentDate: row.sentDate, viewedDate: row.viewedDate}]}).call()
const shown = (decorated?.rows || [])[0] || {}
ec.service.sync().name('org.moqui.ui.NotificationServices.mark#NotificationsViewed').parameters({notificationMessageId: notificationMessageId}).call()
if (ec.message.hasError()) return
// a record that is gone (under the user's filters): the center, with a message
const keys = {'mantle.party.Party': 'partyId', 'mantle.request.Request': 'requestId', 'mantle.work.effort.WorkEffort': 'workEffortId',
    'moqui.resource.wiki.WikiPage': 'wikiPageId', 'mantle.party.communication.CommunicationEvent': 'communicationEventId'}
const keyField = shown.recordEntityName ? keys[shown.recordEntityName] : null
const gone = keyField && shown.recordId && ec.entity.find(shown.recordEntityName).condition(keyField, shown.recordId).count() === 0
if (gone || !shown.openUrl) {
    notice = gone ? ec.l10n.localize('The record of this notification is no longer there') : ec.l10n.localize('This notification has no link')
    screenUrl = '/qapps/Commons/Notifications'
    return
}
if (shown.openIsScreen) screenUrl = shown.openUrl
else redirectUrl = shown.openUrl

viewedCount = 0
const topics = Array.from(ec.entity.find('moqui.security.user.NotificationTopic').useCache(true).disableAuthz().list())
const approvalTopics = new Set(topics.filter((row) => row.approveServiceName).map((row) => row.topic))
const updateTopics = new Set(topics.filter((row) => !row.approveServiceName && row.inboxEnumId === 'NinUpdates').map((row) => row.topic))
const ids = Array.from(ec.entity.find('moqui.security.user.NotificationMessageByUser').condition('userId', ec.user.userId)
        .condition('viewedDate', null).selectField('notificationMessageId,topic').disableAuthz().list())
        .filter((row) => !approvalTopics.has(row.topic) && (updateTopics.has(row.topic) === (inboxEnumId === 'NinUpdates')))
        .map((row) => row.notificationMessageId)
if (!ids.length) return
viewedCount = ec.service.sync().name('org.moqui.ui.NotificationServices.mark#NotificationsViewed')
        .parameters({notificationMessageIdList: ids}).call()?.viewedCount || 0

approvedCount = 0
failedIds = []
const ids = (Array.isArray(notificationMessageId) ? notificationMessageId : String(notificationMessageId).split(','))
        .map((id) => String(id).trim()).filter((id) => id)
for (const id of ids) {
    ec.message.pushErrors()
    try {
        ec.service.sync().name('org.moqui.ui.NotificationServices.approve#NotificationMessage').parameters({notificationMessageId: id})
                .requireNewTransaction(true).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        approvedCount++
    } catch (err) {
        failedIds.push(id)
        ec.logger.warn(`Approve of notification ${id} by ${ec.user.username} failed: ${err && err.message ? err.message : err}`)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
if (failedIds.length) ec.message.addMessage(ec.resource.expand('Not approved: ${ids}', '', {ids: failedIds.join(', ')}), 'warning')

notificationsRows = []
updatesRows = []
const userId = ec.user.userId
if (!userId) return
const provided = new Set(Array.from(providerTopics || []).map((topic) => String(topic)))
const settings = new Map(Array.from(ec.entity.find('moqui.security.user.NotificationTopicUser').condition('userId', userId)
        .disableAuthz().list()).map((row) => [row.topic, row]))
const yn = (value) => value === 'Y' ? 'Y' : 'N'
const topics = Array.from(ec.entity.find('moqui.security.user.NotificationTopic').useCache(true).disableAuthz().list())
        .filter((topic) => topic.isPrivate !== 'Y' || provided.has(topic.topic) || settings.has(topic.topic))
        .sort((a, b) => String(a.description || a.topic).localeCompare(String(b.description || b.topic)))
for (const topic of topics) {
    const mine = settings.get(topic.topic)
    const row = {topic: topic.topic, description: topic.description || topic.topic,
        receiveNotifications: yn(mine?.receiveNotifications || topic.receiveNotifications),
        emailNotifications: yn(mine?.emailNotifications || topic.emailNotifications),
        digest: yn(mine?.digest || topic.digestDefault), hasEmail: !!topic.emailTemplateId, isApproval: !!topic.approveServiceName}
    if (!topic.approveServiceName && topic.inboxEnumId === 'NinUpdates') updatesRows.push(row)
    else notificationsRows.push(row)
}

keyRows = []
const L = (text) => ec.l10n.localize(text)
let overrides = {}
try {
    const text = ec.user.getPreference('KEYMAP')
    const parsed = text ? JSON.parse(text) : {}
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) overrides = parsed
} catch (err) {
    ec.logger.warn(`The KEYMAP preference of ${ec.user.username} is not JSON, ignored: ${err}`)
}
const add = (scope, id, label, keys, where) => {
    const own = overrides[scope] && typeof overrides[scope] === 'object' ? overrides[scope][id] : null
    keyRows.push({scope: scope, id: id, label: label || id, defaultKeys: keys, keys: own || keys, overridden: !!own, where: where})
}
const shell = L('Shell')
add('global', 'palette', L('Search and go to (the palette)'), 'Mod+K', shell)
add('global', 'close', L('Close the tray panel'), 'Esc', shell)
add('global', 'help', L('Keyboard shortcuts'), '?', shell)
add('global', 'quickCreate', L('Create in the current app'), 'c', shell)
for (const map of Array.from(keymaps || [])) {
    const scope = map.scope || 'global'
    for (const key of Array.from(map.keys || [])) {
        if (!key || !key.keys) continue
        add(scope, key.action || key.keys, key.label, key.keys, map.appTitle || null)
    }
}

let overrides = {}
try {
    const text = ec.user.getPreference('KEYMAP')
    const parsed = text ? JSON.parse(text) : {}
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) overrides = parsed
} catch (err) {
    ec.logger.warn(`The KEYMAP preference of ${ec.user.username} was not JSON and is replaced: ${err}`)
}
const value = keys == null ? '' : String(keys).trim().replace(/\s+/g, ' ')
if (value && !/^[A-Za-z0-9+?!\/.,;:\- ]+$/.test(value)) {
    ec.message.addError(ec.resource.expand('Keys like Mod+K, g c or ? only, not ${value}', '', {value: value}))
    return
}
const own = overrides[scope] && typeof overrides[scope] === 'object' ? overrides[scope] : {}
if (!value || value === defaultKeys) delete own[id]
else own[id] = value
if (Object.keys(own).length) overrides[scope] = own
else delete overrides[scope]
keymapText = Object.keys(overrides).length ? JSON.stringify(overrides) : ''
ec.user.setPreference('KEYMAP', keymapText)

const L = (text) => ec.l10n.localize(text)
let states = {}
try {
    const text = ec.user.getPreference('COMMONS_SETUP')
    const parsed = text ? JSON.parse(text) : {}
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) states = parsed
} catch (err) {
    ec.logger.warn(`The COMMONS_SETUP preference of ${ec.user.username} is not JSON, ignored: ${err}`)
}
setupItems = [
    {item: 'mailAccount', icon: 'sym_o_mail', label: L('Add a mail account'), description: L('Read and send your email here'),
        url: '/qapps/Comms/Settings/MailAccounts'},
    {item: 'importContacts', icon: 'sym_o_contacts', label: L('Import contacts'), description: L('From a vCard or CSV file, Google or Outlook'),
        url: '/qapps/Commons/Contacts/Import'},
    {item: 'connectCalendar', icon: 'sym_o_calendar_month', label: L('Connect a calendar'), description: L('Subscribe to a calendar you already use'),
        url: '/qapps/Commons/Settings/Calendars'},
    {item: 'installPhone', icon: 'sym_o_install_mobile', label: L('Install on your phone'),
        description: L('Open this site on your phone and add it to the home screen'), url: null}
].map((entry) => Object.assign(entry, {state: states[entry.item] || null}))
showCard = setupItems.some((entry) => !entry.state)

if (!['mailAccount', 'importContacts', 'connectCalendar', 'installPhone', 'all'].includes(item)) {
    ec.message.addError(ec.resource.expand('No setup item ${item}', '', {item: item}))
    return
}
let states = {}
try {
    const text = ec.user.getPreference('COMMONS_SETUP')
    const parsed = text ? JSON.parse(text) : {}
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) states = parsed
} catch (err) {
    states = {}
}
const items = item === 'all' ? ['mailAccount', 'importContacts', 'connectCalendar', 'installPhone'] : [item]
for (const name of items) {
    if (state === 'done' || state === 'dismissed') { if (item !== 'all' || !states[name]) states[name] = state }
    else delete states[name]
}
ec.user.setPreference('COMMONS_SETUP', JSON.stringify(states))

const L = (text) => ec.l10n.localize(text)
const partyId = ec.user.userAccount?.partyId
if (!partyId) { ec.message.addError(L('Your account has no contact record to hold a photo')); return }
const name = String(contentFile.getName ? contentFile.getName() : contentFile.name || '').replace(/^.*[\/\\]/, '')
const type = String(contentFile.contentType || contentFile.getContentType?.() || '')
// the file is served by its name's type, so the name is an image's, and the type sent, when there is one, too
if (!/\.(png|jpe?g|gif|webp)$/i.test(name) || (type && !/^image\/(png|jpe?g|pjpeg|gif|webp)$/i.test(type))) {
    ec.message.addError(L('Choose an image file: PNG, JPEG, GIF or WebP')); return }
if (Number(contentFile.size ?? contentFile.getSize?.() ?? 0) > 5 * 1024 * 1024) { ec.message.addError(L('The photo may be at most 5 MB')); return }
partyContentId = ec.service.sync().name('mantle.party.PartyServices.create#PartyContent').parameters({partyId: partyId,
    partyContentTypeEnumId: 'PcntFaceImage', contentFile: contentFile, contentDate: ec.user.nowTimestamp, description: name}).call()?.partyContentId
if (ec.message.hasError() || !partyContentId) return
ec.service.sync().name('ironstone.commons.CommonsServices.remove#MyPhoto').parameter('keepPartyContentId', partyContentId).call()

removedCount = 0
const partyId = ec.user.userAccount?.partyId
if (!partyId) return
const folder = `/party/${partyId}/content_`
for (const content of ec.entity.find('mantle.party.PartyContent').condition('partyId', partyId)
        .condition('partyContentTypeEnumId', 'PcntFaceImage').list()) {
    if (keepPartyContentId && content.partyContentId === keepPartyContentId) continue
    const location = content.contentLocation ? String(content.contentLocation) : null
    ec.service.sync().name('delete#mantle.party.PartyContent').parameter('partyContentId', content.partyContentId).call()
    if (ec.message.hasError()) return
    removedCount++
    if (!location || !location.includes(folder + content.partyContentId + '/')) continue
    try {
        const ref = ec.resource.getLocationReference(location)
        if (ref && ref.getExists()) ref.delete()
    } catch (err) {
        ec.logger.warn(`The photo of party ${partyId}: the row of ${location} is removed, the file was not: ${err}`)
    }
}
